// =====================================================================
// SOC-Lite · Escalado de SLA: clasificación, mensaje y SQL de bitácora
// Entrada: una fila por alerta escalada en esta pasada.
// =====================================================================
const fmtDur = (sec) => {
  const s = Math.abs(Number(sec) || 0);
  if (s < 60) return s + ' s';
  if (s < 3600) return Math.floor(s / 60) + ' min';
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  return h + ' h ' + m + ' min';
};
const esc = (v) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
};

const DASH = String($env.DASHBOARD_BASE_URL || $('C · Set parámetros SLA').first().json.DASHBOARD_BASE_URL || 'http://localhost:3000').replace(/\/+$/, '');
const out = [];

for (const item of $input.all()) {
  const a = item.json || {};
  if (!a.alert_id) continue;
  const overdue = Number(a.seconds_overdue || 0) > 0;
  const tier = a.sla_tier || (overdue ? 'vencido' : 'proximo');
  const tierLabel = tier === 'vencido' ? 'SLA VENCIDO' : tier === 'critico' ? 'SLA CRITICO (<5 min)' : 'SLA PROXIMO A VENCER';
  const tierEmoji = tier === 'vencido' ? ':alarm_clock:' : tier === 'critico' ? ':rotating_light:' : ':warning:';
  const sev = String(a.severity || 'medium');
  const prio = sev === 'critical' ? 'p1' : sev === 'high' ? 'p2' : sev === 'medium' ? 'p3' : 'p4';
  const url = DASH + '/alerts/' + a.alert_id;
  const deltaTxt = overdue
    ? 'Vencido hace ' + fmtDur(a.seconds_overdue)
    : 'Vence en ' + fmtDur(a.seconds_left);

  const text = [
    tierEmoji + ' *' + tierLabel + '* — alerta #' + a.alert_id + ' (' + sev.toUpperCase() + ' / ' + prio + ')',
    'Activo: ' + (a.agent_name || 'n/d') + '  |  IP origen: ' + (a.source_ip || 'n/d') + '  |  Regla: ' + (a.rule_id || 'n/d'),
    deltaTxt + '  |  Vencimiento: ' + (a.sla_due_at || 'n/d'),
    'Asignada a: ' + (a.assigned_username || 'SIN ASIGNAR') + '  |  Eventos agrupados: ' + (a.dedup_count || 1),
    String(a.rule_description || ''),
    '<' + url + '|Ver alerta #' + a.alert_id + ' en el dashboard>'
  ].join('\n');

  out.push({
    json: {
      alert_id: Number(a.alert_id),
      alert_fingerprint: a.alert_fingerprint,
      severity: sev,
      priority: prio,
      sla_tier: tier,
      tier_label: tierLabel,
      channel: $env.ESCALATION_CHANNEL || $('C · Set parámetros SLA').first().json.ESCALATION_CHANNEL || '#soc-escalamientos',
      is_overdue: overdue,
      minutes_overdue: Number(a.minutes_overdue || 0),
      seconds_left: Number(a.seconds_left || 0),
      notification_text: text,
      dashboard_url: url,
      escalate_to: sev === 'critical' || overdue ? 'soc_manager' : 'analyst_on_duty',
      sql: {
        alert_id: Number(a.alert_id),
        rule_id: esc(a.rule_id),
        severity: esc(sev),
        sla_tier: esc(tier),
        seconds_left: Number(a.seconds_left || 0),
        seconds_overdue: Number(a.seconds_overdue || 0),
        notification_text: esc(text),
        model_name: esc('sla-escalation-v1'),
        origin_ip: esc($env.N8N_ORIGIN_IP || '10.10.2.90'),
        detail: esc('Escalado automatico de SLA: ' + tierLabel + ' (' + deltaTxt + ') para la alerta #' + a.alert_id + ' [' + sev + '/' + prio + ']')
      }
    }
  });
}

return out;
